import{_ as o,c as e,o as r,a0 as d}from"./chunks/framework.C1J0Vcxi.js";const m=JSON.parse('{"title":"第二十七周：K3 RT24 启动机制全链路调研与 rt-async 移植可行性","description":"","frontmatter":{"title":"第二十七周：K3 RT24 启动机制全链路调研与 rt-async 移植可行性","date":"2026-06-14"},"headers":[],"relativePath":"周报-Oveln/2026-06-14-周报二十七.md","filePath":"周报-Oveln/2026-06-14-周报二十七.md"}'),a={name:"周报-Oveln/2026-06-14-周报二十七.md"};function c(s,t,n,i,p,l){return r(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="第二十七周工作总结" tabindex="-1">第二十七周工作总结 <a class="header-anchor" href="#第二十七周工作总结" aria-label="Permalink to &quot;第二十七周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>rt-async-amp 在 QEMU virt 双核 AMP 方案验证可行后，下一步是移植到真实硬件——<strong>进迭时空 K3 SoC 的 RT24 实时小核</strong>。本周完成了 K3 RT24 启动机制的<strong>全链路调研</strong>：从 BootROM 到 RT24 执行第一条指令，每个环节都定位到确切的源码/寄存器。</p><p>核心结论：<strong>rt-async 可在 RT24 上运行，且无需自实现唤醒逻辑——复用官方 <code>esos.itb</code> 打包链即可。</strong></p><h2 id="_1-目标平台" tabindex="-1">1. 目标平台 <a class="header-anchor" href="#_1-目标平台" aria-label="Permalink to &quot;1. 目标平台&quot;">​</a></h2><p>K3（进迭时空 2026 年 1 月量产的 RISC-V AI SoC）采用大小核 + 实时核的异构设计：</p><table tabindex="0"><thead><tr><th>核</th><th>类型</th><th>数量</th><th>职责</th></tr></thead><tbody><tr><td>X100</td><td>通用大核 (RV64GV)</td><td>8</td><td>跑 Linux</td></tr><tr><td>A100</td><td>AI 核</td><td>8</td><td>GPU/AI 计算</td></tr><tr><td><strong>RT24</strong></td><td><strong>实时小核 (CVA6, RV64GC)</strong></td><td><strong>2</strong></td><td><strong>能效管理、实时任务</strong></td></tr></tbody></table><p>两个 RT24 核（<code>os0_rcpu</code> / <code>os1_rcpu</code>）各自跑独立 RTOS 实例，正是 rt-async 的目标落点。RT24 关键参数：主频 614.4 MHz、os0 链接地址 <code>0x100200000</code>（os1 <code>0x100800000</code>，DDR &gt;4GB）、每核独立 3 MB RAM、官方固件 ESOS（RT-Thread 4.0.4）。</p><h2 id="_2-启动链全链路-核心成果" tabindex="-1">2. 启动链全链路（核心成果） <a class="header-anchor" href="#_2-启动链全链路-核心成果" aria-label="Permalink to &quot;2. 启动链全链路（核心成果）&quot;">​</a></h2><p>之前调研卡在&quot;ELF 加载到 DDR 后，靠什么让 RT24 开始执行&quot;。最终通过 Yocto BSP 仓库定位到真正的 K3 U-Boot（<code>spacemit-com/uboot-2022.10</code>，tag <code>k3-br-v1.0.0</code>），把整条链补全：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① BootROM</span></span>
<span class="line"><span>   └─ 读 STRAP 引脚确定启动介质，加载 U-Boot SPL 到 SRAM 并跳转</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② U-Boot SPL  (board/spacemit/k3/)</span></span>
<span class="line"><span>   ├─ DDR/PMIC/pinctrl 初始化，注册 k3-rproc 驱动</span></span>
<span class="line"><span>   ├─ 从存储读取 esos.itb + u-boot.itb</span></span>
<span class="line"><span>   └─ 解析 FIT 时逐节点回调 board_fit_image_post_process()</span></span>
<span class="line"><span>       ├─ &quot;rcpu0-fw&quot; → rproc_load(0) + rproc_start(0)   ← 唤醒 RT24 核 0</span></span>
<span class="line"><span>       ├─ &quot;rcpu1-fw&quot; → rproc_load(1) + rproc_start(1)   ← 唤醒 RT24 核 1</span></span>
<span class="line"><span>       └─ u-boot/dtb → 正常加载到 DDR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ RT24 被唤醒  (drivers/remoteproc/k3-rproc.c)</span></span>
<span class="line"><span>   └─ 从 0x100200000 取指，执行 startup_gcc.S: _start</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ OpenSBI fw_dynamic → U-Boot proper → Linux</span></span>
<span class="line"><span>   (此时 RT24 早就在跑了)</span></span></code></pre></div><p>三个关键证据：</p><ol><li><strong>FIT 镜像结构</strong>（<code>esos_rt24.its</code>）：<code>rcpu0-fw</code> 节点的 <code>load</code>/<code>entry</code> 均为 <code>&lt;0x1 0x200000&gt;</code>（<code>#address-cells=&lt;2&gt;</code> 的 64 位写法，即 <code>0x100200000</code>），<code>data</code> 指向 <code>rt24_os0_rcpu.elf.lzo</code>。</li><li><strong>SPL 触发 rproc</strong>（<code>board/spacemit/k3/spl.c</code>）：<code>board_fit_image_post_process()</code> 识别 <code>rcpu*-fw</code> 节点名，LZO 解压 ELF 后调用 <code>rproc_load</code> + <code>rproc_start</code>。<strong>唤醒发生在 SPL 阶段，早于 OpenSBI 和 Linux</strong>——主核内核里完全没有 RT24 管理代码（已全树搜索确认）。</li><li><strong>唤醒的确切寄存器</strong>（<code>drivers/remoteproc/k3-rproc.c</code>）：<code>k3_rproc_load()</code> 解除音频域复位、开时钟、允许 RT24 执行、保持复位睡眠、解析 ELF 段拷到 DDR；<code>k3_rproc_start()</code> 设启动入口 PC、设 mhartid、解除软件复位、写唤醒寄存器、轮询同步标志确认 RT24 起来。<strong>整个唤醒不依赖 mailbox、不依赖 SBI ecall，是纯寄存器操作。</strong></li></ol><h2 id="_3-rt24-视角的硬件" tabindex="-1">3. RT24 视角的硬件 <a class="header-anchor" href="#_3-rt24-视角的硬件" aria-label="Permalink to &quot;3. RT24 视角的硬件&quot;">​</a></h2><p>ESOS 设备树给出 RT24 自己看到的地址空间，与主核视角不同：</p><table tabindex="0"><thead><tr><th>外设</th><th>RT24 视角</th><th>QEMU virt 现状</th><th>差异</th></tr></thead><tbody><tr><td><strong>中断控制器</strong></td><td>PLIC <code>0xe0000000</code></td><td>PLIC <code>0x0c000000</code></td><td>仅地址不同，模型一致 ✓</td></tr><tr><td><strong>定时器</strong></td><td>rtimer0 <code>0xc0889000</code></td><td>CLINT mtime</td><td>寄存器模型不同，需重写</td></tr><tr><td><strong>UART</strong></td><td>R_UART0 <code>0xc0881000</code> (PXA-uart)</td><td>NS16550A</td><td>寄存器布局不同，需重写</td></tr><tr><td><strong>UART 时钟</strong></td><td>需先经 CCU <code>0xc0881f00</code> 使能</td><td>默认开启</td><td>加 <code>clk_init()</code></td></tr><tr><td><strong>IPI / 通信</strong></td><td>mailbox3~7</td><td>CLINT MSIP</td><td>机制不同，需适配</td></tr><tr><td><strong>关机</strong></td><td>无 SiFive Test 设备</td><td>写 <code>0x5555</code></td><td>改为 wfi 循环</td></tr></tbody></table><p><strong>中断控制器是 PLIC（不是 APLIC）——最大的好消息</strong>，rt-async 现有 PLIC 驱动逻辑可基本复用，只需改地址。</p><h2 id="_4-移植可行性评估" tabindex="-1">4. 移植可行性评估 <a class="header-anchor" href="#_4-移植可行性评估" aria-label="Permalink to &quot;4. 移植可行性评估&quot;">​</a></h2><p><strong>架构层完全兼容</strong>：ESOS 启动汇编 <code>startup_gcc.S</code> 与 rt-async 的 <code>__start</code>（<code>riscv64-rt/src/start.rs</code>）结构高度一致——清 mie/mip、设 mtvec/gp/sp、清 bss 各步骤都对应得上，trap 入口同样是标准 M-mode 上下文保存/恢复，可直接复用。唯一需处理的是启动禁 FPU（ESOS 设 <code>MSTATUS_FS</code>，当前 rv64imac 无 FPU）。</p><p><strong>加载层零额外工作</strong>：把 rt-async 编译出的 ELF 放进 <code>esos.itb</code> 的 <code>rcpu0-fw</code> 节点，SPL 会自动 <code>rproc_load</code> + <code>rproc_start</code>。复制 <code>esos_rt24.its</code> 把 <code>data</code> 换成自己的 ELF，<code>mkimage</code> 重打包即可。</p><p><strong>待解决的移植点</strong>：</p><table tabindex="0"><thead><tr><th>工作项</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>memory.x 改址 <code>0x100200000</code></td><td>低</td><td>改 ORIGIN/LENGTH</td></tr><tr><td>ISA target 切 <code>riscv64gc</code></td><td>中</td><td>验证 bare-metal target；启动禁 FPU</td></tr><tr><td>重写 <code>Chip::put_str</code> (PXA-UART)</td><td>中</td><td>参考 ESOS <code>ruart</code> 驱动</td></tr><tr><td>UART 时钟使能 (<code>clk_init</code>)</td><td>低</td><td>写 CCU <code>0xc0881f00</code></td></tr><tr><td>重写 <code>TimerChip</code> (rtimer0)</td><td>中</td><td>32-bit 计数器 + match 寄存器</td></tr><tr><td>PLIC 改址 <code>0xe0000000</code></td><td>低</td><td>改 base + context 号</td></tr><tr><td>删除 <code>shutdown</code> (SiFive Test)</td><td>低</td><td>改为 <code>wfi</code> 循环</td></tr><tr><td>IPC：CLINT MSIP → mailbox</td><td>中</td><td>AMP 通信机制需重新设计</td></tr></tbody></table><h2 id="_5-踩坑教训" tabindex="-1">5. 踩坑教训 <a class="header-anchor" href="#_5-踩坑教训" aria-label="Permalink to &quot;5. 踩坑教训&quot;">​</a></h2><p>调研耗时较长，主因几次走错方向：</p><ol><li><strong>找错 U-Boot 仓库</strong>：<code>spacemit-com/u-boot</code> 只有 K1 代码，正确的 K3 U-Boot 是 <code>spacemit-com/uboot-2022.10</code>（tag <code>k3-br-v1.0.0</code>），由 Yocto BSP 帖子才定位到。</li><li><strong>误判加载阶段</strong>：一度以为是 U-Boot proper 用 <code>bootm standalone</code> 加载，实际是 SPL 阶段的 <code>rproc_load</code>/<code>rproc_start</code>。</li><li><strong>误判触发机制</strong>：猜测过 mailbox/SBI ecall，最终确认是纯 PMU + 复位寄存器写入。</li></ol><p>根本教训：<strong>调研技术机制时，定位到源码行号之前不要下结论。</strong> &quot;某仓库只有 K1&quot;和&quot;某仓库存在 K3&quot;是两个不同的事实，不能因前者推断后者不存在；查不到就直接说查不到，不要用&quot;某种机制&quot;&quot;可能&quot;等含糊措辞。</p><h2 id="_6-下周计划" tabindex="-1">6. 下周计划 <a class="header-anchor" href="#_6-下周计划" aria-label="Permalink to &quot;6. 下周计划&quot;">​</a></h2><p>启动 rt-async 移植第一阶段——<strong>先在 RT24 上点亮 UART</strong>：</p><ol><li>新建 <code>modules/chip-k3-rt24/</code>（参考现有 <code>chip-qemu-virt-rt</code>）</li><li>实现 PXA-UART 的 <code>Chip::put_str</code> + CCU 时钟使能</li><li>memory.x 改为 <code>0x100200000</code>，验证链接</li><li>用 <code>esos_rt24_sign.its</code>（无压缩）打包 rt-async ELF</li><li>目标：在 K3 板子 R_UART0 上看到 rt-async 的启动日志</li></ol><p>定时器和 PLIC 留到第二阶段，UART 通路先打通。</p><hr><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><h3 id="源码仓库-本周实际查阅" tabindex="-1">源码仓库（本周实际查阅） <a class="header-anchor" href="#源码仓库-本周实际查阅" aria-label="Permalink to &quot;源码仓库（本周实际查阅）&quot;">​</a></h3><ul><li><strong>esos</strong>（官方 RT24 固件，RT-Thread 4.0.4）：<a href="https://github.com/spacemit-com/esos" target="_blank" rel="noreferrer">https://github.com/spacemit-com/esos</a><ul><li>启动汇编 <code>libcpu/risc-v/spacemit/rt24/startup_gcc.S</code>、链接脚本 <code>bsp/spacemit/platform/rt24/os0_rcpu/gcc.ld</code></li><li>FIT 模板 <code>esos_rt24.its</code> / <code>esos_rt24_sign.its</code>、ENTRY_POINT <code>build.sh:110</code> (<code>0x100200000</code>)</li><li>设备树 <code>bsp/spacemit/platform/rt24/k3.dtsi</code></li></ul></li><li><strong>uboot-2022.10</strong>（K3 U-Boot，tag <code>k3-br-v1.0.0</code>）：<a href="https://github.com/spacemit-com/uboot-2022.10" target="_blank" rel="noreferrer">https://github.com/spacemit-com/uboot-2022.10</a><ul><li>SPL 主流程 <code>board/spacemit/k3/spl.c</code>、额外 FIT 加载 <code>board/spacemit/k3/spl_extra_fit.c</code></li><li><strong>RT24 唤醒驱动</strong> <code>drivers/remoteproc/k3-rproc.c</code>（<code>k3_rproc_load</code> / <code>k3_rproc_start</code>，含全部寄存器定义）</li></ul></li><li><strong>linux-k3</strong>（分支 <code>k3/integration</code>）：<a href="https://github.com/spacemit-com/linux-k3" target="_blank" rel="noreferrer">https://github.com/spacemit-com/linux-k3</a> — 内核中无 RT24/remoteproc 管理代码</li><li><strong>spacemit-yocto</strong>（K3 Yocto BSP，分支 <code>k3</code>）：<a href="https://github.com/yingjie-liu-spacemit/spacemit-yocto" target="_blank" rel="noreferrer">https://github.com/yingjie-liu-spacemit/spacemit-yocto</a> — 指向上述源码仓库的 recipe</li></ul><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li>K3 用户手册（地址映射/中断/外设寄存器）：<a href="https://cdn-resource.spacemit.com/file/chip/K3/k3_um_en.pdf" target="_blank" rel="noreferrer">https://cdn-resource.spacemit.com/file/chip/K3/k3_um_en.pdf</a></li><li>K3 Yocto BSP 上线公告：<a href="https://forum.spacemit.com/t/topic/1239" target="_blank" rel="noreferrer">https://forum.spacemit.com/t/topic/1239</a></li><li>官方文档中心：<a href="https://www.spacemit.com/community/document" target="_blank" rel="noreferrer">https://www.spacemit.com/community/document</a></li></ul>`,36)])])}const u=o(a,[["render",c]]);export{m as __pageData,u as default};
